const js=html.split('<script>')[1].split('</script>')[0];
function el(){return {style:{},textContent:'',className:'',disabled:false,value:'bubble',children:[],appendChild(c){this.children.push(c)},addEventListener(e,f){this['on'+e]=f}};}
