let k=0;while(!els.stepBtn.disabled&&k<5000){els.stepBtn.onclick();k++;}
const h=els.chart.children.map(b=>parseFloat(b.style.height));
if(h.some((v,i)=>i&&h[i-1]>v)||!h.every(_=>true)) throw a;
if(r==0)console.log(a,els.cmpCount.textContent,els.swapCount.textContent,els.playBtn.textContent,els.status.textContent,h.length);}}
console.log('ok')
EOF
